const stdout = $input.first().json.stdout || '';
const start = stdout.indexOf('[');
const end = stdout.lastIndexOf(']');
if (start === -1 || end < start) {
  const stderr = $input.first().json.stderr || stdout.slice(0, 500);
  throw new Error('XGBoost scoring script did not return a JSON array. ' + stderr);
}
const customers = JSON.parse(stdout.slice(start, end + 1));
if (!Array.isArray(customers)) {
  throw new Error('Expected a JSON array of scored customers.');
}
return customers.map((customer) => ({ json: customer }));

